parameters.jsCode:
const aiMessage = $json.choices?.[0]?.message?.content || $json.message?.content || JSON.stringify($json);

let extracted;
try {
  // Clean common wrappers
  const cleaned = aiMessage.replace(/```json\s*|```\s*/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = {
    vendorName: null,
    invoiceNumber: null,
    issueDate: null,
    dueDate: null,
    totalAmount: null,
    currency: null,
    lineItemsSummary: null,
    confidence: 0,
    notes: 'AI response parse failed. Raw: ' + aiMessage.substring(0, 300)
  };
}

// Merge with original email context for downstream nodes
return {
  ...extracted,
  emailSubject: $json.subject || $input.first().json.subject,
  emailFrom: $json.from || $input.first().json.from,
  emailDate: $json.date || $input.first().json.date,
  messageId: $json.messageId || $input.first().json.messageId,
  driveFileUrl: $json.driveFileUrl || null  // will be populated if Drive node runs before
};
